function candidateMatches(seed,job){return traceCandidate(seed,job)!==null&&(typeof validateLevelHistory!=='function'||validateLevelHistory(seed,job));}
function seedTimeline(seed,count){const start=uint64(seed);integer(count,1,100,'Entered roll count');return{firstEnteredSeed:String(start),lastEnteredSeed:String(BigInt.asUintN(64,start+BigInt(count-1))),nextSeed:String(BigInt.asUintN(64,start+BigInt(count))),enteredRollCount:count,nextRollNumber:count+1};}
function nextRoll(seed,job){const rotations=traceCandidate(BigInt(seed),job);if(!rotations)throw Error('Candidate no longer matches.');const timeline=seedTimeline(seed,job.observations.length),nextSeed=BigInt(timeline.nextSeed),draw=drawVisible(nextSeed,job.forgeLevel),group=groupFor(draw),n=group.indices.length,full=(1<<n)-1,variants=new Map();for(let mask of rotations[draw.age+':'+draw.type]??possibleMasks(n)){if(mask===full)mask=0;const available=group.indices.filter((_,j)=>!(mask&(1<<j))),idx=available[(draw.pick>>>1)%available.length];if(!variants.has(idx))variants.set(idx,{idx,name:PRED_CONFIG.names[draw.age+':'+draw.type+':'+idx],stats:statsFor(draw,idx)});}return{seed:String(nextSeed),timeline,age:draw.age,type:draw.type,variants:[...variants.values()]};}
function assess(count,checked,total,informative,complete){return{meter:complete&&count?100/count:0,label:!complete?'Search incomplete':count===0?'No match in this window':count===1?'One candidate in this window':count.toLocaleString()+' candidates remain',canGuess:complete&&count===1&&informative>=3};}
function projectFutureDraw(draw,masks){const group=groupFor(draw),indices=group.indices,n=indices.length,full=(1<<n)-1,nextMasks=new Set(),selected=new Set();for(let mask of masks??possibleMasks(n)){if(mask===full)mask=0;const available=indices.map((idx,j)=>({idx,j})).filter(x=>!(mask&(1<<x.j))),chosen=available[(draw.pick>>>1)%available.length];selected.add(chosen.idx);nextMasks.add(mask|(1<<chosen.j));}const byClass=new Map(),variants=[];for(const idx of selected){const key=draw.type===5?String(PRED_CONFIG.weapons[draw.age+':'+idx]):'all';if(!byClass.has(key))byClass.set(key,statsFor(draw,idx));variants.push({idx,name:PRED_CONFIG.names[draw.age+':'+draw.type+':'+idx],stats:byClass.get(key)});}return{row:{seed:draw.seed,age:draw.age,type:draw.type,variants},nextMasks:[...nextMasks]};}
function futureSequence(startSeed,job,count){integer(count,1,Number.MAX_SAFE_INTEGER,'Future roll count');const rotations=traceCandidate(BigInt(startSeed),job);if(!rotations)throw Error('The recovered seed no longer matches the entered results.');const current=BigInt(seedTimeline(startSeed,job.observations.length).nextSeed);let offset=0;return{count,currentSeed:String(current),next(){if(offset>=count)return null;const draw=drawVisible(BigInt.asUintN(64,current+BigInt(offset)),job.forgeLevel),key=draw.age+':'+draw.type,p=projectFutureDraw(draw,rotations[key]);rotations[key]=p.nextMasks;offset++;return{roll:offset,forgesBefore:offset-1,...p.row};}};}
function filterFuture(rows,options={}){let list=rows.filter(r=>(options.minAge===''||options.minAge==null||r.age>=Number(options.minAge))&&(options.type===''||options.type==null||r.type===Number(options.type))&&(!options.query||(AGES[r.age]+' '+TYPES[r.type]+' '+r.variants.map(v=>v.name).join(' ')).toLowerCase().includes(options.query.toLowerCase())));const sort=options.sort??'queue';if(sort==='rarity')list.sort((a,b)=>b.age-a.age||a.roll-b.roll);else if(sort==='low-rarity')list.sort((a,b)=>a.age-b.age||a.roll-b.roll);else list.sort((a,b)=>a.roll-b.roll);return list;}
