function numericIntervals(stat){const r=PRED_CONFIG.statRanges[stat.k],scale=r.upper-r.lower;return[Math.max(0,Math.ceil(((stat.lower-2e-7)/100-r.lower)/scale*Q)-2),Math.min(Q-1,Math.floor(((stat.upper+2e-7)/100-r.lower)/scale*Q)+2)];}
