            age, chance, items: aItems, coins: aCoins, coinsMin: aMin, coinsMax: aMax,
            avgLevel: aItems > 0 ? aLevel / aItems : 0,
            avgLevelLow: aItems > 0 ? aLow / aItems : 0,
